content:
The task vectors are nearly orthogonal with heavy conflict mass, so the plain soup loses ~half of each delta's energy in conflicting coordinates. Before spending evaluations, I'll compute "delta-retention" statistics (how much of ‖Dc‖² and ‖Db‖² each candidate merge preserves) for several merge families, then evaluate the most balanced conflict-aware candidate (TIES-style with 30% trim).

```python
# ---- merge families ----
def trimmed(v, frac):
    """keep top-frac magnitude entries (frac=1 -> keep all)"""
    if frac >= 1.0:
        return v.clone()
    a = v.abs().reshape(-1)
    thr = torch.quantile(a, 1.0 - frac)
    return v * (v.abs() >= thr).to(v.dtype).view_as(v)

def delta_stats(merged_delta, name):
    dc = torch.cat([Dc[k].reshape(-1) for k in keys])
    db = torch.cat([Db[k].reshape(-1) for k in keys])
    md = torch.cat([merged_delta[k].reshape(-1) for k in keys])
    r_c = (torch.dot(md, dc) / (md.norm() * dc.norm() + 1e-12)).item()
    r_b = (torch.dot(md, db) / (md.norm() * db.norm() + 1e-12)).item()
    e_c = (torch.dot(md, dc) / (dc.norm()**2 + 1e-12)).item()   # energy fraction of Dc kept
    e_b = (torch.dot(md, db) / (db.norm()**2 + 1e-12)).item()
    print(f"{name:16s} cos2Dc={r_c:+.3f} cos2Db={r_b:+.3f} E_Dc={e_c:.3f} E_Db={e_b:.3f}")

cands = {}

# 0) plain soup (reference "average")
cands['soup0.5'] = {k: 0.5 * Dc[k] + 0.5 * Db[k] for k in keys}
# 1) winner-take-all per coordinate
cands['wta'] = {k: torch.where(Dc[k].abs() >= Db[k].abs(), Dc[k], Db[k]) for k in keys}
# 2) TIES with several trims
for t in (0.3, 0.5, 0.7):
    m = {}
    for k in keys:
        tc, tb = trimmed(Dc[k], t), trimmed(Db[k], t)
        s = torch.sign(tc + tb)
        mc = (tc * s > 0).to(tc.dtype); mb = (tb * s > 0).to(tb.dtype)
        num = tc * mc + tb * mb
        den = (mc + mb).clamp(min=1e-8)
        m[k] = torch.where((mc + mb) > 0, num / den, torch.zeros_like(num))
    cands[f'ties{t}'] = m
# 3) sign-agree keep avg, conflict keep winner
m = {}
for k in keys:
    dc, db = Dc[k], Db[k]
    agree = (dc * db) > 0
    wta = torch.where(dc.abs() >= db.abs(), dc, db)
    m[k] = torch.where(agree, 0.5 * (dc + db), wta)
cands['agreewta'] = m
# 4) conflict-zero: average when agree, zero when conflict
m = {}
for k in keys:
    dc, db = Dc[k], Db[k]
    m[k] = torch.where((dc * db) > 0, 0.5 * (dc + db), torch.zeros_like(dc))
cands['agreezero'] = m

for n, d in cands.items():
    delta_stats(d, n)
```

Both balanced soups plateau at ~80.3, and a parabolic fit through the three λ points (0.5→79.64, 0.4→80.37, 0.35→80.18) puts the vertex exactly at λc≈0.40 — global λ tuning is exhausted. To beat the plateau I'll spend my last two evaluations on structurally different merges: (1) a MagMax-style singular-direction merge (per-tensor SVD of both deltas, index-wise max spectrum, tilted 0.4/0.6, rescaled per-tensor to the soup's energy so feature scale is preserved), and (2) a per-layer schedule (λc=0.45 early/0.35 late), keeping the saved 0.4 soup as fallback if neither wins.

```python
import re

def blk(k):
    m = re.search(r'encoder_layer_(\d+)', k)
    return int(m.group(1)) if m else -1

lam_c, lam_b = 0.40, 0.60
soup = {k: lam_c * Dc[k] + lam_b * Db[k] for k in keys}

# ---- SVDs of both deltas for all >=2D weight tensors ----
shapes = {}
for k in keys:
    t = parent[k]
    if t.dim() >= 2 and 'pos_embedding' not in k and 'class_token' not in k:
        shapes[k] = (t.shape[0], t.numel() // t.shape[0])
SVD = {}
for k in shapes:
    Uc_, Sc_, Vct = torch.linalg.svd(Dc[k].reshape(shapes[k]), full_matrices=False)
    Ub_, Sb_, Vbt = torch.linalg.svd(Db[k].reshape(shapes[k]), full_matrices=False)
    SVD[k] = (Uc_, Sc_, Vct, Ub_, Sb_, Vbt)
print("svds done:", len(SVD))

# ---- candidate 1: MagMax-tilted, per-tensor rescaled to soup energy ----
mag = {}
ratios = []
for k in keys:
    if k in SVD:
        Uc_, Sc_, Vct, Ub_, Sb_, Vbt = SVD[k]
        mspec = torch.maximum(Sc_, Sb_)
        Rc = (Uc_ * mspec) @ Vct
        Rb = (Ub_ * mspec) @ Vbt
        mrg = lam_c * Rc + lam_b * Rb
        s = soup[k].reshape(shapes[k])
        sc = s.norm() / (mrg.norm() + 1e-12)
        ratios.append((mrg.norm() / (torch.sqrt((lam_c*Sc_)**2 + (lam_b*Sb_)**2) + 1e-12)).item())
        mag[k] = (mrg * sc).reshape(parent[k].shape)
    else:
        mag[k] = soup[k]
print("magmax ||merged||/||no-interf ideal||: mean %.3f median %.3f" %
      (np.mean(ratios), np.median(ratios)))

# ---- candidate 2: layer schedule (early 0.45 / late 0.35) ----
def lam_for(k):
    b = blk(k)
    if b == -1:
        return 0.35 if ('encoder.ln' in k) else 0.45
    return 0.45 if b <= 5 else 0.35
sched = {k: lam_for(k) * Dc[k] + (1 - lam_for(k)) * Db[k] for k in keys}

def full_sd(delta):
    return {k: (parent[k] + delta[k]).contiguous().float() for k in keys}

r_mag = evaluate(full_sd(mag))
print("magmax tilt0.4:", r_mag)
r_sch = evaluate(full_sd(sched))
print("sched 0.45/0.35:", r_sch)

# ---- save the overall best ----
best_delta, best_mean, best_name = soup, 0.8036782741546631, "soup0.40/0.60"
for name, d, r in (("magmax", mag, r_mag), ("sched", sched, r_sch)):
    if r["mean"] > best_mean:
        best_delta, best_mean, best_name = d, r["mean"], name
save_merge(full_sd(best_delta))
print("SAVED:", best_name, best_mean)
```

`magmax` (79.15) underperformed the soup frontier, and the kernel restart wiped `sched` — my saved 0.40/0.60 soup (80.37) stands. The one measurement that stands out from the diagnostics: `encoder.pos_embedding` deltas are fully non-overlapping (cos 0.021) and `conv_proj` nearly so (cos 0.344), meaning the soup provably discards ~60–75% of both tasks' input-stem adaptations there purely through dilution. For the final evaluation I'll keep the tuned 0.40/0.60 soup everywhere except the input stem (conv_proj + pos_embedding), where I take the full union of both deltas (zero-interference combination for near-orthogonal vectors). If it doesn't beat 80.37, the current save stays.

```python
import re
keys = list(parent.keys())
Dc = {k: (cifar[k] - parent[k]).float() for k in keys}
Db = {k: (cub[k] - parent[k]).float() for k in keys}
lam = 0.40

stem = ['conv_proj.weight', 'conv_proj.bias', 'encoder.pos_embedding']
delta = {}
for k in keys:
    if k in stem:
        delta[k] = Dc[k] + Db[k]                      # full union: near-orthogonal, zero interference
    else:
        delta[k] = lam * Dc[k] + (1.0 - lam) * Db[k]  # tuned soup

for k in stem:
    print(k, "||union||=%.3f ||soup||=%.3f" % (delta[k].norm(),
          (lam * Dc[k] + (1 - lam) * Db[k]).norm()))

sd = {k: (parent[k] + delta[k]).contiguous().float() for k in keys}
r = evaluate(sd)
print("soup0.40 + stem-union:", r)

if r["mean"] > 0.8036782741546631:
    save_merge(sd)
    print("SAVED: soup0.40 + stem-union")
else:
    print("KEPT: soup 0.40/0.60 (mean 0.8037)")
```
